    if (id === 'wfPick') { const pk = ctl.value; return K({ title: 'Pick', chip: pk === 'plateau' ? 'each cell is averaged with its neighbours first' : 'the single best cell wins', tone: '', value: pk === 'plateau' ? 'Plateau centre' : 'Best cell', vlabel: 'How the winner is chosen', plain: pk === 'plateau' ? 'Each cell\'s score is replaced by the average of itself and its valid neighbours, so an isolated spike loses to a broad good area.' : 'The cell with the highest score on the training window wins, even if it is an isolated spike.', secs: [], use: 'Plateau centre is the safer pick.' }); }
