    if (id === 'wfR') return K({ title: 'Train : test', chip: 'the size of the training window against the test window', tone: '', value: esc(ctl.value) + ' : 1', vlabel: 'Train to test ratio', plain: 'The training window is this many times as long as the test window that follows it.', secs: [], use: '3 : 1 or more gives the tuning enough data.' });
