  add('#wfBody .bt-empty p', () => K({ title: 'Walk-forward testing', chip: 'run on request only', tone: '', plain: 'History is cut into folds. Each fold tunes the two parameters on a training window, then trades the <b>next, unseen</b> window with the winners. Only those unseen windows count. If the stitched result holds up, the strategy survives being re-tuned on a schedule.', secs: [], use: 'Pick the two parameters and press Run walk-forward.' }));
