      plain: esc(T(el)), secs: [sec('The rule, in order', tbl([{ c: ['Above the baseline', 'unseen return above 0, at least 60% of windows profitable, efficiency of 50% or more, and a chance by luck of 10% or less'], on: st === 'up' }, { c: ['Not distinguishable from luck', 'profitable overall, but under one of the conditions above'], on: st === 'neutral' }, { c: ['Not robust', 'unseen return at 0 or below'], on: st === 'dn' }]))],
