    if (id === 'cpRisk') { const r = +ctl.value, hi = g(() => RISK_HIGH, 5), cap = g(() => RISK_CAP, 10); return K({ title: 'Risk %', chip: r > cap ? `above the ${cap}% the ticket refuses` : r > hi ? `above the ${hi}% the ticket calls high` : `inside the ${hi}% line of the ticket`, tone: r > cap ? 'bad' : r > hi ? 'warn' : '', value: `${esc(ctl.value)}<small>%</small>`, vlabel: 'Share of the account risked', sub: A.ok ? `${usd(A.risk)} of ${usd(A.acc)}` : '', plain: 'The share of the account that you accept to lose if the stop is hit. The calculator turns it into a size.', secs: [sec('Against the ticket\'s limits', scale([{ w: hi, label: 'normal', tone: 'ok' }, { w: cap - hi, label: 'high', tone: 'warn' }, { w: 5, label: 'refused', tone: 'bad' }], 0, cap + 5, cl(r, 0, cap + 5), x => nfx(x >= cap + 5 && r > x ? r : x, 1) + '%') + p(`The ticket colours risk amber above <b>${hi}%</b> and refuses an order above <b>${cap}%</b>; this calculator does not limit it.`))], use: 'Take the size from here to the ticket with the button below the result.' }); }
    if (id === 'cpSL') return K({ title: `Stop (${g(() => unitWord(A.s), 'pips')})`, chip: 'the distance from the entry to the stop', tone: '', value: `${esc(ctl.value)}<small> ${g(() => unitWord(A.s), 'pips')}</small>`, vlabel: 'Stop distance', sub: A.ok ? `${usd(A.sl * A.pv)} per lot` : '', plain: 'The distance to the stop in the instrument\'s own unit. The wider the stop, the smaller the size that keeps the same risk.', secs: [], use: 'Use the stop your plan needs, not the one that gives the size you want.' });
    if (id === 'cpToTk') return K({ title: 'Send size and stop to the ticket', chip: 'fills New order: nothing is sent', tone: '', plain: 'Switches to Trade and puts this size and this stop in the New order ticket. You still choose the side and press the order button. It shows only while the size has no warning.', secs: [], use: 'Check the ticket\'s own risk line before you send.' });
    if (id === 'pvLots') return K({ title: 'Lots', chip: 'the size the figures are worked for', tone: '', value: esc(ctl.value), vlabel: 'Position size', plain: 'The size of the position. The sheet\'s minimum, maximum and step apply: below the minimum or above the maximum an order is refused and the result says so.', secs: [], use: 'Try your usual size.' });
    if (id === 'pvLev') return K({ title: 'Leverage', chip: ctl.readOnly ? 'fixed by the jurisdiction cap in Settings' : 'a what-if up to the sheet maximum', tone: '', value: `1:${esc(ctl.value)}`, vlabel: 'Leverage used for the margin', sub: T(document.getElementById('pvLevTag')), plain: ctl.readOnly ? 'The jurisdiction cap you set in Settings fixes the leverage, so the field cannot be changed.' : 'With no jurisdiction cap you can try any leverage up to the instrument sheet\'s maximum. If it is not your account\'s leverage, the result adds a note saying so.', secs: [], watch: 'The margin the account really needs uses the account\'s leverage, not this field.', use: 'Use it to see what a higher or lower leverage would require.' });
    if (id === 'cgStart') return K({ title: 'Start (USD)', chip: 'the balance the compounding starts from', tone: '', value: usd(+ctl.value), vlabel: 'Starting balance', plain: 'The starting amount. It is typed; it is not read from your account.', secs: [], use: 'Try your own balance.' });
    if (id === 'cgRet') return K({ title: 'Monthly return %', chip: 'the same return every month, no losing month', tone: '', value: `${esc(ctl.value)}<small>%</small>`, vlabel: 'Return per month', plain: 'The return applied to the balance every month. The compounding assumes it repeats exactly, with no losing month: real results vary.', secs: [], watch: 'A monthly return you cannot hold for the whole period gives a number that means nothing.', use: 'Be conservative: the result grows fast with this input.' });
