  const calcLabel = el => { const ctl = el.matches('select,input,button') ? el : el.querySelector('select,input,button'); return ctl ? calcCtl(ctl) : null; };
  add('.calcs .calc label, .calcs .calc select, .calcs .calc input, .calcs .calc button#cpToTk', calcLabel, { empty: true });
  add('.calcs .calc > h3', el => { const t = lo(el), D = { 'position size': ['Position size', 'Turns the risk you accept and a stop distance into a size: the amount at risk divided by the loss per lot at that stop, rounded down to the sheet\'s volume step so the risk never goes above what you asked.', 'lots = floor(account × risk % ÷ (stop × pip value per lot) ÷ step) × step'], 'pip / point value & margin': ['Pip / point value & margin', 'What one pip (or point) is worth in USD for a size, and the margin, notional and spread cost of that position.', 'pip value = lots × contract size × pip × USD rate of the quote; margin = notional ÷ leverage'], compounding: ['Compounding', 'What a balance becomes when the same return is added every month. It is arithmetic, not a forecast.', 'final = start × (1 + monthly return)^months'] }[t]; if (!D) return null;
    return K({ title: D[0], chip: 'a calculator: it only works the numbers out', tone: '', plain: D[1], secs: [sec('The formula', p(`<b class="mono">${esc(D[2])}</b>`))], use: 'Hover each field and each result for its figures.' }); });
  add('#cpUnit, #pvLevTag', el => { const A = cpIn(); if (el.id === 'cpUnit') return K({ title: 'Stop unit', chip: 'the instrument\'s own unit', tone: '', value: esc(T(el)), vlabel: 'Unit of the stop', plain: 'Pips on FX pairs, points on CFDs: the unit changes with the instrument you pick.', secs: [], use: 'Type the stop in this unit.' });
    return K({ title: 'Leverage of the account', chip: 'what the account allows on this instrument', tone: '', value: esc(T(el)), vlabel: 'Profile', plain: 'The leverage the account uses on this instrument: the sheet\'s, or your choice up to its maximum, capped by the jurisdiction you set. The maximum is the most you can type in the field.', secs: [], use: 'Change the cap in Settings if it is not what you expect.' }); });

  const rowCard = el => { const lab = lo(el.querySelector('span')), b = el.querySelector('b'), v = esc(T(b)), box = el.closest('#cpOut') ? 'cp' : el.closest('#pvOut') ? 'pv' : 'cg';
    if (box === 'cp') { const A = cpIn(); if (!A.ok) return null; const u = g(() => unitWord(A.s), 'pips');
      const D = { 'position size': () => K({ title: 'Position size', chip: A.lots < A.vMin - 1e-9 ? 'below the sheet\'s minimum: no position fits' : A.lots > A.vMax + 1e-9 ? 'above the sheet\'s maximum: refused' : 'rounded down to the volume step: never more risk than asked', tone: A.lots < A.vMin - 1e-9 || A.lots > A.vMax + 1e-9 ? 'bad' : 'ok', value: v, vlabel: 'Size that risks the amount asked', sub: `${nfx(A.raw, 4)} before rounding down`,
          plain: 'The largest size, in whole volume steps, whose loss at the stop does not exceed the risk amount.', secs: [sec('The arithmetic', tbl([{ c: ['Risk amount', `${usd(A.acc)} × ${nfx(A.r, 2)}% = ${usd(A.risk)}`] }, { c: ['Loss per lot at the stop', `${nfx(A.sl, 1)} ${u} × ${usd(A.pv)} = ${usd(A.sl * A.pv)}`] }, { c: ['Size before rounding', nfx(A.raw, 4)] }, { c: ['Volume step', String(A.step)] }, { c: ['Size', String(A.lots)], on: true }]))], watch: 'The ticket also refuses an order whose notional is above ' + g(() => MAX_NOTIONAL_X) + '× equity.', use: 'Send it to the ticket with the button, or type it in New order.' }),
        units: () => K({ title: 'Units', chip: 'the size in the instrument\'s own units', tone: '', value: v, vlabel: 'Size in base units', plain: 'The size above expressed in the units of the asset: base currency on FX, shares, ounces or barrels, or money per point on index CFDs.', secs: [], use: 'Cross-check it with the contract size on the instrument sheet.' }),
        'amount at risk': () => K({ title: 'Amount at risk', chip: A.atRisk <= A.risk + 1e-9 ? 'at or under the risk you asked for' : 'above the risk you asked for', tone: A.atRisk <= A.risk + 1e-9 ? 'ok' : 'bad', value: v, vlabel: 'Loss if the stop is hit', sub: `asked ${usd(A.risk)}`, plain: 'The size × the stop distance × the value of one pip per lot. It is below the amount asked because the size was rounded down to the volume step.', secs: [sec('The arithmetic', p(`${A.lots} lots × ${nfx(A.sl, 1)} ${u} × ${usd(A.pv)} = <b>${usd(A.atRisk)}</b>`))], watch: 'It does not include the spread, slippage or a gap through the stop.', use: 'Compare it with the equity you can afford to lose.' }),
        'pip value': () => K({ title: 'Pip value', chip: 'what one pip is worth for this size', tone: '', value: v, vlabel: `Value of one ${g(() => unitWord(A.s, true), 'pip')} for the size`, plain: 'Size × contract size × the pip, in USD at the current rate of the quote currency.', secs: [], use: 'Multiply it by a distance to get a USD result.' }),
        'point value': () => K({ title: 'Point value', chip: 'what one point is worth for this size', tone: '', value: v, vlabel: 'Value of one point for the size', plain: 'Size × contract size × the point, in USD.', secs: [], use: 'Multiply it by a distance to get a USD result.' }),
        'margin at profile': () => K({ title: 'Margin at profile', chip: 'what this size locks up at the account\'s leverage', tone: '', value: v, vlabel: 'Notional ÷ leverage', sub: `notional ${usd(A.n)}`, plain: 'The margin the account would hold for this position with the leverage of its profile (the sheet\'s, your choice, or the jurisdiction cap).', secs: [sec('The arithmetic', p(`${usd(A.n)} ÷ ${A.lev} = <b>${usd(A.n / A.lev)}</b>`))], watch: 'It is the margin only: the stop-out level and free margin are in the ticket and the status bar.', use: 'Keep it well below the account\'s free margin.' }) }[lab];
      return D ? D() : null; }
    if (box === 'pv') { const s = document.getElementById('pvSym').value, l = +document.getElementById('pvLots').value, lev = +document.getElementById('pvLev').value, m = mk(s); if (!m || !(l > 0)) return null; const n = g(() => notionalUsd(s, l)), u1 = g(() => unitWord(s, true), 'pip'), q = g(() => Engine.quote(s));
      const D = { 'pip value': () => K({ title: 'Pip value', chip: 'what one pip is worth for this size', tone: '', value: v, vlabel: `Value of one ${u1}`, plain: 'Lots × contract size × the pip × the USD rate of the quote currency.', secs: [sec('The arithmetic', p(`${l} lots × ${nf0.format(m.size)} × ${m.pip} × the USD value of 1 ${esc(m.quote)} = <b>${esc(T(b))}</b>`))], use: 'Use it to turn a distance in pips into dollars.' }), 'point value': () => K({ title: 'Point value', chip: 'what one point is worth for this size', tone: '', value: v, vlabel: 'Value of one point', plain: 'Lots × contract size × the point, in USD.', secs: [], use: 'Use it to turn a distance in points into dollars.' }),
        units: () => K({ title: 'Units', chip: 'the size in the instrument\'s own units', tone: '', value: v, vlabel: 'Size in base units', plain: 'Lots × contract size, in the units of the asset.', secs: [], use: 'Cross-check it with the instrument sheet.' }),
        margin: () => K({ title: 'Margin', chip: 'notional ÷ leverage', tone: '', value: v, vlabel: 'Margin for this size', sub: `1:${lev}`, plain: 'The notional value of the position divided by the leverage in the field.', secs: [sec('The arithmetic', p(`${usd(n)} ÷ ${lev} = <b>${usd(n / lev)}</b>`))], watch: 'The field may be a what-if: the account\'s real margin uses its own leverage.', use: 'Compare it with your free margin.' }),
        notional: () => K({ title: 'Notional', chip: 'the full value of the position', tone: '', value: v, vlabel: 'Size × price, in USD', plain: 'The value of the position at the live price, in USD: on FX the base currency amount converted to USD, on CFDs the size × price × the USD rate.', secs: [], watch: 'The ticket refuses an order above ' + g(() => MAX_NOTIONAL_X) + '× equity.', use: 'It is the figure that leverage divides.' }),
        'spread cost': () => K({ title: 'Spread cost', chip: 'the spread paid on entry, in USD', tone: '', value: v, vlabel: 'Spread × pip value', sub: q ? `spread now ${nfx(q.spread, 2)} ${u1}` : '', plain: 'The spread of the live quote, in pips or points, times the value of one pip for this size: what the position loses the moment it opens, before the price moves.', secs: [], watch: 'It is the spread of the quote now; the sheet\'s night spread and news widening differ.', use: 'Compare it with the profit you aim for: on a small target it is a big share.' }) }[lab];
      return D ? D() : null; }
    const st = +document.getElementById('cgStart').value, ret = +document.getElementById('cgRet').value / 100, mo = +document.getElementById('cgM').value, fin = st * Math.pow(1 + ret, mo);
    const D = { 'final balance': () => K({ title: 'Final balance', chip: 'start × (1 + return)^months', tone: '', value: v, vlabel: 'Balance after the months', plain: 'The balance if the same return were added every month with no losing month.', secs: [sec('The arithmetic', p(`${usd(st)} × (1 + ${nfx(ret * 100, 2)}%)^${mo} = <b>${usd(fin)}</b>`))], watch: 'Real results vary: this is arithmetic only.', use: 'Change the return first: it moves the result most.' }),
      'total gain': () => K({ title: 'Total gain', chip: 'final balance − start', tone: '', value: v, vlabel: 'Gain over the months', plain: 'The final balance minus the starting balance.', secs: [sec('The arithmetic', p(`${usd(fin)} − ${usd(st)} = <b>${usdS(fin - st)}</b>`))], use: 'Read it with Total return.' }),
      'total return': () => K({ title: 'Total return', chip: 'final ÷ start − 1', tone: '', value: v, vlabel: 'Return over all the months', plain: 'The growth of the balance over the whole period, as a percentage.', secs: [sec('The arithmetic', p(`${usd(fin)} ÷ ${usd(st)} − 1 = <b>${pct((fin / st - 1) * 100, 1)}</b>`))], use: 'Compare it with Annualised.' }),
      annualised: () => K({ title: 'Annualised', chip: '(1 + monthly return)^12 − 1', tone: '', value: v, vlabel: 'Return of twelve months at this rate', plain: 'What twelve months at the monthly return give when compounded: (1 + monthly return)^12 − 1.', secs: [sec('The arithmetic', p(`(1 + ${nfx(ret * 100, 2)}%)^12 − 1 = <b>${pct((Math.pow(1 + ret, 12) - 1) * 100, 1)}</b>`))], watch: 'It assumes the same return in every month, with no losing month.', use: 'Be sceptical of any figure that depends on twelve equal months.' }) }[lab];
    return D ? D() : null; };
  add('.calcs .calc-out > div:not(.calc-err):not(.calc-note)', rowCard);
  add('.calcs .calc-out > .calc-err, .calcs .calc-out > .calc-note, .calcs .calc-out > p.note', el => { const t = T(el), cn = el.matches('.calc-note'), nt = el.matches('p.note');
    return K({ title: nt ? 'Arithmetic only' : cn ? 'What-if note' : t.split(/[:.—]/)[0].slice(0, 52), chip: nt ? 'the same return every month, no losing month' : cn ? 'this figure is not your account\'s' : 'the figure cannot be used as it stands', tone: nt || cn ? 'warn' : 'bad', plain: esc(t), secs: [], use: nt ? 'Read the figure as arithmetic, not a forecast.' : cn ? 'Set the leverage to the account\'s to see its real margin.' : 'Fix the input named in the message.' }); });

  // =====================================================================================================
  //  no hover on self-explanatory actions (the standing rule): opt-out candidates, also listed in the notes of T10
